  // ---------- conférences de presse dynamiques ----------
  'press.q.redCard': "{player} a été expulsé aujourd'hui. A-t-il laissé tomber l'équipe ?", 'press.q.redCard.2': "Qu'avez-vous dit à {player} après son carton rouge ?",
  'press.q.hero': "{player} a été remarquable aujourd'hui. Est-il le meilleur du championnat en ce moment ?", 'press.q.hero.2': 'Pouvez-vous vous passer de {player} vu son niveau actuel ?',
  'press.q.newSigning': "{player} vient d'arriver. Combien de temps lui faudra-t-il pour faire la différence ?", 'press.q.newSigning.2': "{player} est-il l'homme qui fera décoller cette équipe ?",
  'press.q.youngster': "{player} n'a que {age} ans. Est-il prêt à jouer régulièrement ?", 'press.q.youngster.2': "Tout le monde parle de {player}. Jusqu'où peut-il aller ?",
